#!/bin/bash

VERSION_STRING='V01'

YELLOW='\e[33m'
RED='\e[31m'
GREEN='\e[32m'
NC='\e[0m'

directory="$( cd "$( dirname "${BASH_SOURCE[0]}" )" >/dev/null 2>&1 && pwd )"

readOptionsFromConfigFile() {
    source $directory/gnbMirroringConfig.sh
    if [ $? -eq 0 ]; then
        echo -e "\n${YELLOW}Read options from gnbMirroringConfig.sh${NC}"
    else
        echo -e "\n${RED}Config file (gnbMirroringConfig.sh) not found${NC}"
        exit
    fi
}

readOptionsFromComonFile() {
    source $directory/common_funcs.sh
    if [ $? -eq 0 ]; then
        echo -e "\n${YELLOW}Read options from common_funcs.sh${NC}"
    else
        echo -e "\n${RED}Config file (common_funcs.sh) not found${NC}"
        exit
    fi
}



if [ $XTRACE = 'on' ]; then
    set -x
fi

captureData() {
  if [ "$BB_SLOT_5" == "true" ] || [ "$BB_SLOT_1" == "true" ]; then
        bsh 1:0 "dbgnet mirror port set sport 7  dport 18 direction both enable"
		if [ "$CAPTURING_INTERFACE" == "default" ];then
        bsh 1:0 "tcpdump -i etha01 -W $NUMBER_OF_FILES -C $FILE_SIZE_MBYTES -vvv -w /tmp/tcpdump_L2L1_bip_filtering_$FILTERING.pcap '$filtered_messages'"
		else
        bsh 1:0 "tcpdump -i $CAPTURING_INTERFACE -W $NUMBER_OF_FILES -C $FILE_SIZE_MBYTES -vvv -w /tmp/tcpdump_L2L1_bip_filtering_$FILTERING.pcap '$filtered_messages'"
		fi
	fi

}

readOptionsFromConfigFile
readOptionsFromComonFile
parseCommandLineOptions "$@"
captureData
